  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

import { fetch } from 'undici'
import { TARGET_ENDPOINTS, DocumentedEndpoint } from './fixtures.js'

export interface ConnectorConfig {
  hubApiKey: string
  hubApiBaseUrl?: string // e.g. 'https://api.hubapi.com' or 'https://api.us2.hubapi.com'
}

export interface ContactInput {
  email: string
  properties?: Record<string, unknown>
}

export interface ContactResult {
  vid: number
  isNew: boolean
}

function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((e) => e.method === method.toUpperCase() && urlMatches(e.url, url))
}

function urlMatches(template: string, actual: string): boolean {
  try {
    const tUrl = new URL(template.replace(/{[^}]+}/g, '*').replace(/:[^/]+/g, '*').replace(/<[^>]+>/g, '*'))
    const aUrl = new URL(actual)
    if (tUrl.hostname !== aUrl.hostname) return false
    const tParts = tUrl.pathname.split('/').filter(Boolean)
    const aParts = aUrl.pathname.split('/').filter(Boolean)
    if (tParts.length !== aParts.length) return false
    return tParts.every((tp, i) => tp === '*' || tp === aParts[i])
  } catch {
    return false
  }
}

function buildUrl(baseUrl: string, email: string): string {
  const encodedEmail = encodeURIComponent(email)
  return `${baseUrl.replace(/\/+$/, '')}/contacts/v1/contact/createOrUpdate/email/${encodedEmail}`
}

export async function createOrUpdateContact(
  input: ContactInput,
  config: ConnectorConfig,
  customFetch: typeof fetch = fetch
): Promise<ContactResult> {
  if (!input.email) {
    throw new Error('Required field "email" is missing')
  }

  const baseUrl = config.hubApiBaseUrl || 'https://api.hubapi.com'
  const url = buildUrl(baseUrl, input.email)

  const body = {
    properties: [
      { name: 'email', value: input.email },
      ...(input.properties ? Object.entries(input.properties).map(([name, value]) => ({ name, value })) : [])
    ]
  }

  const response = await customFetch(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.hubApiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} - ${url} - ${text}`)
  }

  const data = await response.json() as ContactResult
  return data
}

